def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Count patterns
    opp_c = 0
    opp_d = 0
    cc = 0
    cd = 0
    dc = 0
    dd = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
        else:
            opp_d += 1
        if a == 'C' and b == 'C':
            cc += 1
        elif a == 'C' and b == 'D':
            cd += 1
        elif a == 'D' and b == 'C':
            dc += 1
        else:
            dd += 1

    # Early game: build trust
    if n < 4:
        return 'C'

    # Determine recent behavior (last 8 rounds)
    recent = history[-8:] if n >= 8 else history
    rn = len(recent)
    rec_opp_c = sum(1 for a, b in recent if b == 'C')
    rec_opp_d = rn - rec_opp_c
    rec_cc = sum(1 for a, b in recent if a == 'C' and b == 'C')

    # ---------- Endgame handling ----------
    # Last 15 rounds: if opponent has been cooperative, exploit late
    # but keep some cooperation to preserve case where they punish back.
    if n >= 85:
        remaining = 100 - n
        # If opponent is mostly cooperative, defect in final few rounds
        if opp_c * 100 >= n * 80:
            if remaining <= 6:
                return 'D'
            # Probe occasionally
            if rng.random() < 0.4:
                return 'D'
            return 'C'
        # Opponent mostly defective: defect
        if opp_d * 100 >= n * 60:
            return 'D'
        # Mixed: mirror last with slight defection bias
        if history[-1][1] == 'C':
            return 'D' if rng.random() < 0.5 else 'C'
        return 'D'

    # ---------- Opponent is overwhelmingly cooperative ----------
    if opp_d == 0 and n >= 6:
        # We can exploit, but keep them cooperating.
        # Defect occasionally for bonus points.
        rate = 0.25
        if n >= 30:
            rate = 0.35
        if n >= 60:
            rate = 0.45
        if rng.random() < rate:
            return 'D'
        return 'C'

    if opp_c * 100 >= n * 90 and n >= 10:
        # Very cooperative opponent. Exploit more as match progresses.
        rate = 0.15 + (n / 100.0) * 0.35
        if rng.random() < rate:
            return 'D'
        return 'C'

    # ---------- Opponent is overwhelmingly defective ----------
    if opp_d * 100 >= n * 85 and n >= 4:
        # Punish but still probe occasionally
        if rng.random() < 0.9:
            return 'D'
        return 'C'

    if rec_opp_d >= 6:
        return 'D'

    # ---------- Opponent just defected ----------
    if history[-1][1] == 'D':
        # If we cooperated last round, retaliate once (proportional response)
        if history[-1][0] == 'C':
            # If opponent rarely defects, this was likely noise/stray - forgive
            if opp_d * 100 <= n * 15 and n >= 6:
                # Forgive: cooperate to restore mutual cooperation
                return 'C'
            # Otherwise retaliate
            return 'D'

        # We defected last round. Decide whether to continue punishment or forgive.
        # If mutual defection recently, try to restore cooperation.
        if rec_cc == 0 and rec_opp_d >= 2:
            # We are in a defection spiral. Try conciliatory move occasionally.
            if rng.random() < 0.35:
                return 'C'
            return 'D'

        # Opponent may have defected intermittently. If they've been mostly cooperative
        # overall, forgive.
        if opp_c * 100 >= n * 60:
            if rng.random() < 0.4:
                return 'C'
            return 'D'

        return 'D'

    # ---------- Opponent cooperated this round ----------
    # If we defected last round, they didn't retaliate. Don't push too hard.
    if history[-1][0] == 'D':
        # If opponent has been very forgiving, continue exploiting moderately.
        if opp_d * 100 <= n * 20 and n >= 8:
            if rng.random() < 0.4:
                return 'D'
            return 'C'
        # Otherwise, return to cooperation to repair
        return 'C'

    # Both cooperated. Preserve cooperation, with occasional strategic probe.
    # Only probe when opponent has shown cooperative history and enough data.
    if n >= 20:
        coop_rate = opp_c / n
        if coop_rate > 0.75:
            # Small chance of defect to grab DC, especially mid-game
            if rng.random() < 0.08:
                return 'D'

    # If opponent alternates CD/CD/CD pattern, exploit their pattern.
    if n >= 6:
        alt = 0
        for i in range(2, n):
            if history[i][1] != history[i - 2][1]:
                alt += 1
        if alt >= n - 3 and n >= 6:
            # Predicting opponent next move as opposite of last
            return 'D' if history[-1][1] == 'C' else 'C'

    return 'C'
